    async def create_virtual_numbers_jobs(
        self,
        *,
        message: str,
        number: str,
        service_name: str,
        charset: SmsCharsetEnum | None = None,
        class_: SmsClassEnum | None = None,
        coding: SmsCodingEnum | None = None,
        differed_period: int | None = None,
        priority: SmsPriorityEnum | None = None,
        receivers: list[str] | None = None,
        receivers_document_url: str | None = None,
        receivers_slot_id: str | None = None,
        tag: str | None = None,
        validity_period: int | None = None,
    ) -> SmsSmsSendingReport:
        """
        POST /1.0/sms/{serviceName}/virtualNumbers/{number}/jobs

        Send SMS

        Args:
            charset: The sms coding
            class_: Deprecated: The sms class
            coding: Deprecated: the coding is deduced from the message and its charset
            differed_period: The time -in minute(s)- to wait before sending the message
            message: The sms message
            number: The virtual number
            priority: The priority of the message
            receivers: The receivers list
            receivers_document_url: The receivers document url link in csv format
            receivers_slot_id: The receivers document slot id
            service_name: The internal name of your SMS offer
            tag: The identifier group tag
            validity_period: The maximum time -in minute(s)- before the message is
                dropped
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/1.0/sms/{serviceName}/virtualNumbers/{number}/jobs",
                number=number,
                serviceName=service_name,
            ),
            body={
                "charset": charset,
                "class": class_,
                "coding": coding,
                "differedPeriod": differed_period,
                "message": message,
                "priority": priority,
                "receivers": receivers,
                "receiversDocumentUrl": receivers_document_url,
                "receiversSlotId": receivers_slot_id,
                "tag": tag,
                "validityPeriod": validity_period,
            },
        )
        return SmsSmsSendingReport.model_validate(data)

